/* Original N3 teaching selection. Stable IDs are independent of the legacy examples. */
const N3_UNITS=[];
const N3_MODULES=['行动与时间','原因与条件','判断与建议','表达与沟通'];
function n3Add(title,vocab,points,reading,listening){
 const id='n3u'+String(N3_UNITS.length+1).padStart(2,'0');
 const grammar=points.map(([title,rule,pitfall,examples,q,options,answer,why],i)=>({id:id+'g'+i,title,rule,pitfall,examples,q,options:options.split('|'),answer,why}));
 const text=([text,translation,qs],kind)=>({text,translation,ids:qs.map((_,i)=>id+kind+i),questions:qs.map(([q,options,answer,why],i)=>({id:id+kind+i,q,options:options.split('|'),answer,why}))});
 N3_UNITS.push({id,title,module:Math.floor(N3_UNITS.length/6),vocab:vocab.split(';').map(v=>v.split('|')),grammar,reading:text(reading,'r'),listening:text(listening,'l')});
}
